import { defineConfig } from 'vite-plus'

// Files generated by tools. They are never formatted or linted by hand. drizzle-kit writes the
// snapshots and the journal of migrations/meta, and reads them back as it wrote them.
const generated = [
  '**/dist/**',
  '**/.wrangler/**',
  '**/worker-configuration.d.ts',
  '**/migrations/meta/**',
]

// Test fixtures whose bytes matter: the formatter would rewrite the Markdown under test.
const fixtures = ['tests/fixtures/content/**']

export default defineConfig({
  staged: {
    '*': 'vp check --fix',
  },
  fmt: {
    semi: false,
    singleQuote: true,
    ignorePatterns: [...generated, ...fixtures],
  },
  lint: {
    plugins: ['typescript', 'unicorn', 'oxc', 'import', 'node'],
    jsPlugins: [{ name: 'vite-plus', specifier: 'vite-plus/oxlint-plugin' }],
    options: { typeAware: true, typeCheck: true },
    ignorePatterns: generated,
    rules: {
      'vite-plus/prefer-vite-plus-imports': 'error',
      // Workers cancel promises nobody awaits, so a dropped promise is a silent bug.
      'typescript/no-floating-promises': 'error',
      'typescript/no-misused-promises': 'error',
      'typescript/no-explicit-any': 'error',
    },
    overrides: [
      {
        // Packages take configuration as arguments; process.env would be a hidden input.
        files: ['packages/*/src/**'],
        rules: { 'node/no-process-env': 'error' },
      },
      {
        // Tests build typed values through helpers instead of casting with `as`.
        files: ['**/*.test.ts', 'tests/**'],
        rules: {
          'typescript/consistent-type-assertions': ['error', { assertionStyle: 'never' }],
        },
      },
      {
        // Tests that run inside workerd use @cloudflare/vitest-plugin, which
        // needs the real `vitest` imports rather than `vite-plus/test`.
        files: ['**/*.workerd.test.ts'],
        rules: { 'vite-plus/prefer-vite-plus-imports': 'off' },
      },
    ],
  },
  test: {
    // Each package folder is a project (its own vite.config.ts, if any, applies). A package
    // whose tests also run in workerd adds vitest.workerd.config.ts (core, ADR-018).
    // Worker apps expose their test configs as vitest.config.ts or vitest.*.config.ts.
    projects: [
      'packages/*',
      'packages/*/vitest.*.config.ts',
      'apps/*/vitest.config.ts',
      'apps/*/vitest.*.config.ts',
      'templates/*/vitest.config.ts',
      'examples/*/vitest.config.ts',
      {
        test: {
          name: 'repo',
          include: ['scripts/**/*.test.ts', 'tests/**/*.test.ts'],
          exclude: ['tests/acceptance/**', 'tests/conformance/**'],
          environment: 'node',
        },
      },
    ],
  },
  run: {
    cache: { scripts: false, tasks: true },
    tasks: {
      // The pre-commit hook runs check:commit; CI runs check:push.
      'check:commit': { command: 'vp check', cache: false },
      'check:push': {
        command: [
          'vp check',
          'vp test',
          'vp run -r build',
          'node scripts/check-bins.ts',
          'vp run -r publint',
          'vp run -r types:check',
        ],
        cache: false,
      },
    },
  },
})
